import mri from 'mri'
import {
  Command,
  GlobalCommand,
  type CommandConfig,
  type CommandExample,
  type HelpCallback,
} from './command.ts'
import { getRuntimeProcessArgs } from './runtime.ts'
import {
  camelcaseOptionName,
  getFileName,
  getMriOptions,
  setByType,
  setDotProp,
} from './utils.ts'
import type { OptionConfig } from './option.ts'

interface ParsedArgv {
  args: ReadonlyArray<string>
  options: {
    [k: string]: any
  }
}

export class CAC extends EventTarget {
  /** The program name to display in help and version message */
  name: string
  commands: Command[]
  globalCommand: GlobalCommand
  matchedCommand?: Command
  matchedCommandName?: string
  /**
   * Raw CLI arguments
   */
  rawArgs: string[]
  /**
   * Parsed CLI arguments
   */
  args: ParsedArgv['args']
  /**
   * Parsed CLI options, camelCased
   */
  options: ParsedArgv['options']

  showHelpOnExit?: boolean
  showVersionOnExit?: boolean

  /**
   * @param name The program name to display in help and version message
   */
  constructor(name = '') {
    super()
    this.name = name
    this.commands = []
    this.rawArgs = []
    this.args = []
    this.options = {}
    this.globalCommand = new GlobalCommand(this)
    this.globalCommand.usage('<command> [options]')
  }

  /**
   * Add a global usage text.
   *
   * This is not used by sub-commands.
   * @guarantee ok.global-usage adds a global usage text, which is not used by sub-commands
   */
  usage(text: string): this {
    this.globalCommand.usage(text)
    return this
  }

  /**
   * Add a sub-command
   * @guarantee ok.creates-command creates and returns a command instance for `name` and `description`
   * @guarantee ok.required-arguments in a command name, angled brackets indicate required arguments and square brackets indicate optional arguments ("deploy <folder>" requires `folder`, "build [project]" makes `project` optional)
   * @guarantee ok.variadic only the last argument can be variadic, written with "..." at the start of its name ("build <entry> [...otherFiles]"), and then it is passed as an array
   * @guarantee ok.default-command a command name with no name and only brackets ("[...files]") is the default command, used when no other command is matched
   * @guarantee ok.config-allow-unknown-options `config.allowUnknownOptions` allows unknown options in this command
   * @guarantee ok.config-ignore-default `config.ignoreOptionDefaultValue` leaves the default value of an option out of the parsed options and only displays it in the help message
   */
  command(
    rawName: string,
    description?: string,
    config?: CommandConfig,
  ): Command {
    const command = new Command(rawName, description || '', config, this)
    command.globalCommand = this.globalCommand
    this.commands.push(command)
    return command
  }

  /**
   * Add a global CLI option.
   *
   * Which is also applied to sub-commands.
   * @guarantee ok.global-option adds a global option
   * @guarantee ok.config-default `config.default` is the default value of the option (`--type <type>` with `default: "node"` defaults `type` to "node")
   * @guarantee ok.config-type-array when `config.type` is `[]`, the option value is an array, and a conversion function such as `[String]` is invoked on the option value
   * @guarantee ok.camel-case an option in kebab-case is mapped to camelCase, so `--clear-screen` and `--clearScreen` both map to `options.clearScreen`
   * @guarantee ok.option-brackets in an option name, angled brackets indicate that a string or number value is required and square brackets indicate that the value can also be `true`
   * @guarantee ok.negated-option with `--no-config` and `--config <path>`, the default value of `config` is `true` and the flag `--no-config` sets it to `false`
   * @guarantee ok.repeated-option an option given once gives a single value ("--include project-a" gives `{ include: "project-a" }`) and given twice gives an array (`{ include: ["project-a", "project-b"] }`)
   */
  option(rawName: string, description: string, config?: OptionConfig): this {
    this.globalCommand.option(rawName, description, config)
    return this
  }

  /**
   * Show help message when `-h, --help` flags appear.
   *
   * @guarantee ok.help-flags outputs the help message when the `-h` or `--help` flag appears
   * @guarantee ok.callback the optional `callback` receives the help sections, each with an optional `title` and a `body`, so the help text can be post-processed before it is displayed
   */
  help(callback?: HelpCallback): this {
    this.globalCommand.option('-h, --help', 'Display this message')
    this.globalCommand.helpCallback = callback
    this.showHelpOnExit = true
    return this
  }

  /**
   * Show version number when `-v, --version` flags appear.
   *
   * @guarantee ok.default-flags outputs the version number when the `-v` or `--version` flag appears, because `customFlags` is "-v, --version" by default
   * @guarantee ok.custom-flags `customFlags` replaces the flags that output the version number
   * @guarantee ok.in-help the version number is also used in the help message
   */
  version(version: string, customFlags = '-v, --version'): this {
    this.globalCommand.version(version, customFlags)
    this.showVersionOnExit = true
    return this
  }

  /**
   * Add a global example.
   *
   * This example added here will not be used by sub-commands.
   */
  example(example: CommandExample): this {
    this.globalCommand.example(example)
    return this
  }

  /**
   * Output the corresponding help message
   * When a sub-command is matched, output the help message for the command
   * Otherwise output the global one.
   *
   * @guarantee ok.output outputs the help message
   */
  outputHelp(): void {
    if (this.matchedCommand) {
      this.matchedCommand.outputHelp()
    } else {
      this.globalCommand.outputHelp()
    }
  }

  /**
   * Output the version number.
   *
   */
  outputVersion(): void {
    this.globalCommand.outputVersion()
  }

  private setParsedInfo(
    { args, options }: ParsedArgv,
    matchedCommand?: Command,
    matchedCommandName?: string,
  ) {
    this.args = args
    this.options = options
    if (matchedCommand) {
      this.matchedCommand = matchedCommand
    }
    if (matchedCommandName) {
      this.matchedCommandName = matchedCommandName
    }
    return this
  }

  unsetMatchedCommand(): void {
    this.matchedCommand = undefined
    this.matchedCommandName = undefined
  }

  /**
   * Parse argv
   * @guarantee ok.parsed-argv returns an object with `args`, an array of strings, and `options`, an object of the parsed options
   * @guarantee ok.default-argv `argv` is `process.argv` by default
   * @guarantee ok.available-after-parse after the call, `cli.rawArgs`, `cli.args`, `cli.options` and `cli.matchedCommand` are available
   * @guarantee ok.run-false with `{ run: false }` it parses the arguments without running the command, which can then be run with `runMatchedCommand`
   */
  parse(
    argv?: string[],
    {
      run = true,
    }: {
      /** Whether to run the action for matched command */
      run?: boolean | undefined
    } = {},
  ): ParsedArgv {
    if (!argv) {
      const runtimeProcessArgs = getRuntimeProcessArgs()
      if (!runtimeProcessArgs) {
        throw new Error(
          'No argv provided and runtime process argv is not available.',
        )
      }
      argv = runtimeProcessArgs
    }

    this.rawArgs = argv
    if (!this.name) {
      this.name = argv[1] ? getFileName(argv[1]) : 'cli'
    }

    let shouldParse = true

    // Search sub-commands
    for (const command of this.commands) {
      const parsed = this.mri(argv.slice(2), command)

      const commandName = parsed.args[0]
      if (command.isMatched(commandName)) {
        shouldParse = false
        const parsedInfo = {
          ...parsed,
          args: parsed.args.slice(1),
        }
        this.setParsedInfo(parsedInfo, command, commandName)
        this.dispatchEvent(
          new CustomEvent(`command:${commandName}`, { detail: command }),
        )
      }
    }

    if (shouldParse) {
      // Search the default command
      for (const command of this.commands) {
        if (command.isDefaultCommand) {
          shouldParse = false
          const parsed = this.mri(argv.slice(2), command)
          this.setParsedInfo(parsed, command)
          this.dispatchEvent(new CustomEvent('command:!', { detail: command }))
        }
      }
    }

    if (shouldParse) {
      const parsed = this.mri(argv.slice(2))
      this.setParsedInfo(parsed)
    }

    if (this.options.help && this.showHelpOnExit) {
      this.outputHelp()
      run = false
      this.unsetMatchedCommand()
    }

    if (
      this.options.version &&
      this.showVersionOnExit &&
      this.matchedCommandName == null
    ) {
      this.outputVersion()
      run = false
      this.unsetMatchedCommand()
    }

    const parsedArgv = { args: this.args, options: this.options }

    if (run) {
      this.runMatchedCommand()
    }

    if (!this.matchedCommand && this.args[0]) {
      this.dispatchEvent(new CustomEvent('command:*', { detail: this.args[0] }))
    }

    return parsedArgv
  }

  private mri(
    argv: string[],
    /** Matched command */ command?: Command,
  ): ParsedArgv {
    // All added options
    const cliOptions = [
      ...this.globalCommand.options,
      ...(command ? command.options : []),
    ]
    const mriOptions = getMriOptions(cliOptions)

    // Extract everything after `--` since mri doesn't support it
    let argsAfterDoubleDashes: string[] = []
    const doubleDashesIndex = argv.indexOf('--')
    if (doubleDashesIndex !== -1) {
      argsAfterDoubleDashes = argv.slice(doubleDashesIndex + 1)
      argv = argv.slice(0, doubleDashesIndex)
    }

    let parsed = mri(argv, mriOptions)
    parsed = Object.keys(parsed).reduce(
      (res, name) => {
        return {
          ...res,
          [camelcaseOptionName(name)]: parsed[name],
        }
      },
      { _: [] },
    )

    const args = parsed._

    const options: { [k: string]: any } = {
      '--': argsAfterDoubleDashes,
    }

    // Set option default value
    const ignoreDefault =
      command && command.config.ignoreOptionDefaultValue
        ? command.config.ignoreOptionDefaultValue
        : this.globalCommand.config.ignoreOptionDefaultValue

    const transforms = Object.create(null)

    for (const cliOption of cliOptions) {
      if (!ignoreDefault && cliOption.config.default !== undefined) {
        for (const name of cliOption.names) {
          options[name] = cliOption.config.default
        }
      }

      // If options type is defined
      if (
        Array.isArray(cliOption.config.type) &&
        transforms[cliOption.name] === undefined
      ) {
        transforms[cliOption.name] = Object.create(null)

        transforms[cliOption.name].shouldTransform = true
        transforms[cliOption.name].transformFunction = cliOption.config.type[0]
      }
    }

    // Set option values (support dot-nested property name)
    for (const [key, value] of Object.entries(parsed)) {
      if (key !== '_') {
        const keys = key.split('.')
        setDotProp(options, keys, value)
        setByType(options, transforms)
      }
    }

    return {
      args,
      options,
    }
  }

  /**
   * @guarantee ok.run runs the matched command after `parse` was called with `{ run: false }`, and its result can be awaited when the command action returns a Promise
   */
  runMatchedCommand(): any {
    const { args, options, matchedCommand: command } = this

    if (!command || !command.commandAction) return

    command.checkUnknownOptions()

    command.checkOptionValue()

    command.checkRequiredArgs()

    command.checkUnusedArgs()

    const actionArgs: any[] = []
    command.args.forEach((arg, index) => {
      if (arg.variadic) {
        actionArgs.push(args.slice(index))
      } else {
        actionArgs.push(args[index])
      }
    })
    actionArgs.push(options)
    return command.commandAction.apply(this, actionArgs)
  }
}
